package patusfenixv2

import (

    "gno.land/p/nt/grc721/v0"
    "gno.land/p/nt/grc721/metadata/v0"
)

const metadataURL = "https://patusworld.com/patus-testnet/1.json"

var (
    collection *grc721.Token
    ledger     *grc721.PrivateLedger
    nftMeta    *metadata.Metadata
    metaLedger *metadata.Ledger
)

func init(cur realm) {
    collection, ledger = grc721.NewToken(
        "Patus Fenix Test",
        "PFT",
        0,
        cur,
    )

    nftMeta, metaLedger = metadata.NewMetadata(ledger)
}

// MintTest acuna un unico NFT de prueba.
// La wallet que ejecuta la funcion recibe el NFT.
func MintTest(cur realm) string {
    if collection.TotalSupply() >= 1 {
        return "Patus Fenix has already been minted"
    }

    owner := cur.Previous().Address()

    if err := ledger.Mint(owner, "1"); err != nil {
        return err.Error()
    }

    if err := metaLedger.SetTokenURI("1", metadataURL); err != nil {
        return err.Error()
    }

    return "Patus Fenix minted successfully"
}

// Permite consultar la URL de metadatos del NFT.
func TokenURI(tokenID string) string {
    uri, err := nftMeta.TokenURI(grc721.TokenID(tokenID))
    if err != nil {
        return ""
    }
    return uri
}

// Permite consultar cuantos NFT existen.
func TotalSupply() int64 {
    return collection.TotalSupply()
}

// Pagina informativa del contrato.
func Render(path string) string {
    return "Patus Fenix - GRC721 Test NFT on Onyx"
}

// Devuelve la direccion propietaria del NFT.
func OwnerOf() string {
    owner, err := collection.OwnerOf("1")
    if err != nil {
        return ""
    }
    return owner.String()
}

package patusfenixv2

import (
    "testing"

    "gno.land/p/nt/testutils/v0"
    "gno.land/p/nt/urequire/v0"
)

func TestPatusFenixMint(cur realm, t *testing.T) {
    // Verificar que inicialmente no hay NFTs.
    urequire.Equal(t, int64(0), TotalSupply())

    // Simular la llamada desde una wallet de prueba.
    alice := testutils.TestAddress("alice")

    result := func() string {
        return MintTest(cross(cur))
    }()

    urequire.Equal(t, "Patus Fenix minted successfully", result)

    // Comprobar que existe exactamente un NFT.
    urequire.Equal(t, int64(1), TotalSupply())

    // Comprobar que el NFT tiene un propietario.
owner := OwnerOf()
urequire.True(t, owner != "")
urequire.True(t, owner != "g1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqd8f3t")

    // Comprobar la URL de los metadatos.
    urequire.Equal(
        t,
        "https://patusworld.com/patus-testnet/1.json",
        TokenURI("1"),
    )

    // Un segundo mint no debe crear otro NFT.
    second := MintTest(cross(cur))
    urequire.Equal(t, "Patus Fenix has already been minted", second)
    urequire.Equal(t, int64(1), TotalSupply())

    // Verificar que la dirección de prueba es válida.
    urequire.True(t, alice.IsValid())
}

